SELECT k,SUM(v),AVG(v),COUNT(v),COUNT(*) FROM t GROUP BY k;
SELECT s,k,SUM(v),COUNT(*) FROM t GROUP BY s,k;
SELECT s,k,SUM(v),COUNT(*) FROM t WHERE v > 0 GROUP BY s,k ORDER BY s,k;
SELECT k,COUNT(*) FROM t WHERE v > 100 GROUP BY k;
SELECT k AS "Group",SUM(v) AS "Total",AVG(v) AS mean FROM t GROUP BY k ORDER BY "Total" DESC,"Group" NULLS LAST;
SELECT k,COUNT(*) AS n,COUNT(k) AS nn,SUM(v) AS total,AVG(v) AS avg FROM t GROUP BY k ORDER BY k;
SELECT k,SUM(n),AVG(n),COUNT(n),COUNT(NULL),SUM(NULL),AVG(NULL) FROM t GROUP BY k;
SELECT k,SUM(d),AVG(d),SUM(d * 1.25),AVG(d * 1.25) FROM t GROUP BY k;
SELECT k,COUNT(v),COUNT(v),SUM(v),SUM(v),AVG(v),AVG(v) FROM t GROUP BY k;
SELECT k,COUNT(*) FROM t WHERE v IS NULL GROUP BY k ORDER BY k NULLS FIRST;
SELECT k,COUNT(*) FROM t WHERE k IS NULL GROUP BY k;
SELECT k FROM t GROUP BY k;
SELECT SUM(v),k,COUNT(*) FROM t GROUP BY k ORDER BY 2 DESC;
SELECT k % 2,COUNT(*),SUM(v) FROM t GROUP BY k % 2;
SELECT COALESCE(s,'missing'),COUNT(*),AVG(v) FROM t GROUP BY COALESCE(s,'missing');
SELECT CASE WHEN k IS NULL THEN NULL WHEN k=1 THEN X'' ELSE X'00ff' END AS b,COUNT(*) FROM t GROUP BY CASE WHEN k IS NULL THEN NULL WHEN k=1 THEN X'' ELSE X'00ff' END;
SELECT f,COUNT(*),SUM(v) FROM t GROUP BY f;
SELECT k,COUNT(CASE WHEN denom=0 THEN NULL ELSE CAST(1.0 / denom AS INTEGER) END) FROM t GROUP BY k;
SELECT k,SUM(v),COUNT(*) FROM t WHERE v > 0 AND k IS NOT NULL GROUP BY k ORDER BY 2,k;
